  ((select id from examen), 2030, $q$Las designaciones y promociones de funcionarios/as y empleados/as en las defensorías cuya titularidad se encuentre definitivamente vacante, serán realizadas por:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "El Ministerio de Justicia y Derechos Humanos, teniendo en cuenta la planta de personal de la dependencia."}, {"clave": "b", "texto": "El/la Defensora General de la nación, teniendo en cuenta la planta de personal de la dependencia."}, {"clave": "c", "texto": "La Corte Suprema de Justicia de la Nación, teniendo en cuenta la planta de personal de la dependencia."}]$q$::jsonb, $q$b$q$, $q$mpd-guia-preguntas$q$, $q$Ingreso, cargos e incompatibilidades$q$, 'media', false),
