  ((select id from examen), 2032, $q$El Defensor General de la Nación deberá asegurar:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "La contratación de estudios contables externos para que se encarguen del manejo administrativo-financiero de la institución."}, {"clave": "b", "texto": "La delegación del manejo administrativo-financiero de la institución en la Procuración General de la Nación."}, {"clave": "c", "texto": "La autarquía financiera del Ministerio Público de la Defensa administrando un presupuesto de recursos atendido con cargo al Tesoro Nacional y con recursos propios."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
  ((select id from examen), 2033, $q$La defensoría General de la Nación es:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "La sede de actuación de todos los defensores públicos de la Ciudad Autónoma de Buenos Aires."}, {"clave": "b", "texto": "La sede de actuación del Defensor General de la Nación."}, {"clave": "c", "texto": "La sede de actuación de los curadores y tutores públicos."}]$q$::jsonb, $q$b$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
  ((select id from examen), 2034, $q$Los/las defensores/as Públicos en ejercicio de sus funciones deberán:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "No afiliarse a partidos o agrupaciones políticas ni militar activamente en ellos, sin previa autorización expresa del/de la presidente/a de la Corte Suprema de Justicia de la Nación."}, {"clave": "b", "texto": "Afiliarse al partido político que haya obtenido mayor cantidad de votos en las últimas elecciones."}, {"clave": "c", "texto": "No afiliarse a partidos o agrupaciones políticas ni militar activamente en ellos sin previa autorización expresa del/de la Defensor/a General de la Nación."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
