  ((select id from examen), 2047, $q$A los efectos de asegurar su autarquía financiera, el Ministerio Público:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Contará con crédito presupuestario propio , el que será atendido sólo con recursos específicos."}, {"clave": "b", "texto": "No contará con crédito presupuestario propio."}, {"clave": "c", "texto": "Contará con crédito presupuestario propio, el que será atendido con cargo al Tesoro Nacional y con recursos propios."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
  ((select id from examen), 2048, $q$El/la agente que fuera designado/a o electo/a para el desempeño de los cargos electivos o representativos en asociaciones sindicales con personería gremial, tendrá derecho a:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "El agente tiene vedado el ejercicio de actividades gremiales."}, {"clave": "b", "texto": "Una licencia por el término que dure el mandato, con goce de haberes."}, {"clave": "c", "texto": "Una licencia por el término que dure el mandato, sin goce de haberes, con la posibilidad excepcional de que el/la Defensor/a General de la Nación la conceda con goce de haberes si se reunieran ciertas condiciones."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Deberes y derechos del personal$q$, 'media', false),
  ((select id from examen), 2049, $q$Cuando un magistrado actúe en cumplimiento de indicaciones emanadas del Defensor General de la Nación:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Sólo podrá dejar a salvo su opinión personal en causas penales."}, {"clave": "b", "texto": "Podrá dejar a salvo su opinión personal."}, {"clave": "c", "texto": "No podrá dejar a salvo su opinión personal."}]$q$::jsonb, $q$b$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
  ((select id from examen), 2050, $q$El Ministerio Público de la Defensa posee una organización:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Jerárquica."}, {"clave": "b", "texto": "Horizontal."}, {"clave": "c", "texto": "Descentralizada."}]$q$::jsonb, $q$a$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
  ((select id from examen), 2051, $q$En caso de incumplimiento de los deberes a su cargo, el Procurador General de la Nación y el Defensor General de la Nación, podrán imponer a los magistrados que componen el Ministerio Público Fiscal y el Ministerio Público de la Defensa, respectivamente, las siguientes sanciones disciplinarias:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Suspensión por término de 72 horas."}, {"clave": "b", "texto": "Exoneración directa."}, {"clave": "c", "texto": "Multa de hasta el veinte por ciento (20 %) de sus remuneraciones mensuales."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Régimen disciplinario$q$, 'media', false),
  ((select id from examen), 2052, $q$El Ministerio Público:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Recibe instrucciones del Poder Ejecutivo Nacional."}, {"clave": "b", "texto": "Recibe instrucciones de los jueces."}, {"clave": "c", "texto": "Ejerce su función sin sujeción a instrucciones o directivas emanadas de órganos ajenos a su estructura."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'alta', false),
  ((select id from examen), 2053, $q$Los aspirantes a ingresar como personal del MPD deberán:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Ser mayor de 21 años."}, {"clave": "b", "texto": "Ser mayor de 18 años."}, {"clave": "c", "texto": "Ser mayor de 16 años."}]$q$::jsonb, $q$b$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'media', false),
  ((select id from examen), 2054, $q$Los magistrados del Ministerio Público gozan de estabilidad en su empleo:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Por un periodo de 10 años renovable por otros 10."}, {"clave": "b", "texto": "Toda la vida, sin limitación."}, {"clave": "c", "texto": "Mientras dure su buena conducta, hasta los 75 años de edad."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Deberes y derechos del personal$q$, 'media', false),
  ((select id from examen), 2055, $q$El Defensor General de la Nación es el jefe máximo del Ministerio Público de la Defensa, no podrá imponer sanciones disciplinarias a magistrados, funcionarios y empleados del Ministerio Público de la Defensa:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Fuera de las establecidas en la Constitución Nacional."}, {"clave": "b", "texto": "Fuera de las establecidas en el Código Penal."}, {"clave": "c", "texto": "Fuera de las establecidas en el régimen jurídico respectivo."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Régimen disciplinario$q$, 'media', false),
  ((select id from examen), 2056, $q$Los magistrados del Ministerio Público sólo podrán ser removidos de sus cargos:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Por el tribunal de enjuiciamiento contemplado en la Ley Orgánica del Ministerio Público de la Defensa de la Nación."}, {"clave": "b", "texto": "Por el Consejo de la Magistratura."}, {"clave": "c", "texto": "Por opinión conjunta del Defensor General de la Nación y del Procurador General de la Nación."}]$q$::jsonb, $q$a$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'alta', false),
