  ((select id from examen), 2058, $q$Las permutas entre el personal de las distintas dependencias se produce:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Con la mera conformidad de los/as agentes involucrados."}, {"clave": "b", "texto": "Con la mera conformidad de los titulares de las dependencias en las cuales los/as agentes involucrados prestan funciones."}, {"clave": "c", "texto": "Con la previa autorización expresa del/de la Defensor/a General de la Nación."}]$q$::jsonb, $q$c$q$, $q$mpd-guia-preguntas$q$, $q$Estructura y autonomía del MPD$q$, 'alta', false),
  ((select id from examen), 2059, $q$La licencia con goce de haberes para rendir examen podrá ser acordada:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Hasta un máximo de veinte días laborales por año calendario, en períodos de hasta cinco días."}, {"clave": "b", "texto": "Hasta un máximo de diez materias por año calendario, en período de hasta cinco días."}, {"clave": "c", "texto": "En períodos de dos horas diarias en horario laboral, en oficinas especialmente adaptadas para ello, en periodos de hasta cinco días por materia."}]$q$::jsonb, $q$a$q$, $q$mpd-guia-preguntas$q$, $q$Deberes y derechos del personal$q$, 'alta', false)
on conflict (exam_id, orden) do update set
  enunciado        = excluded.enunciado,
  tipo             = excluded.tipo,
  opciones         = excluded.opciones,
  respuesta_correcta = excluded.respuesta_correcta,
  fuente_normativa = excluded.fuente_normativa,
  -- El tema tampoco se pisa: si alguien lo corrigió a mano al revisar, la
  -- propuesta de la regla no tiene por qué ganarle.
  tema             = coalesce(questions.tema, excluded.tema),
  confianza        = excluded.confianza,
  -- revisada NO se pisa: si alguien ya revisó una pregunta a mano, volver a
  -- correr esto no le saca el tilde.
  revisada         = questions.revisada;

-- MPF · practico · investigacion
-- fuentes: mpf-modelos-manual, mpf-preguntero-nexo
with examen as (
  select e.id from exams e
    join concursos c on c.id = e.concurso_id
   where c.organismo = 'mpf' and c.cargo = 'Técnico administrativo' and c.anio = 2026
     and e.instancia = 'practico' and e.modalidad = 'investigacion'
)
insert into questions (
  exam_id, orden, enunciado, tipo, opciones, respuesta_correcta,
  fuente_normativa, tema, confianza, revisada
) values
  ((select id from examen), 3001, $q$En el falo Itzcovich, Mabel c/ ANSES s/ reajustes varios (fa lo Itzcovich) la Corte Suprema de Justicia de la Nación:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Declaró la constitucionalidad de la ley 24.463 de Solidaridad Previsional sancionada en 1995."}, {"clave": "b", "texto": "Declaró la plena participación y legitimidad de la Corte Suprema para resolver todos los litigios vinculados a la materia previsional."}, {"clave": "c", "texto": "Declaró la inconstitucionalidad del art. 19 de la ley 24.463 de Solidaridad Previsional por establecer la competencia ordinaria de la Corte Suprema en estos casos."}]$q$::jsonb, $q$c$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3002, $q$En el fallo calvo y pesini , rocío c/ cordoba prov. de s/amparo la corte:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Se declaró incompetente por considerar que los litigios pronviciales son de absoluta potestad de sus organismos."}, {"clave": "b", "texto": "Declaró la competencia originaria y la inc. del art 15 de la ley 7625 de la provincia de córdoba por exigir la nac. argentina para ingresar como persona permanente en un hospital público."}, {"clave": "c", "texto": "Resolvió en concordancia con lo dispuesto en la ley de la prov. de córdoba al considerar que el personal de salud de los hospitales públicos debe ser de nacionalidad argentina."}]$q$::jsonb, $q$b$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3003, $q$Realice una búsqueda web a través de la página del MPF y encuentre la Resolución PGN 2636/15 que adecua la organización del MPF a los lineamientos de la ley orgánica del MPF. Responda: ¿En qué se convirtió el programa de acceso a la justicia?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "En la dirección general de acceso a la justicia."}, {"clave": "b", "texto": "En la fiscalía general de acceso a la justicia."}, {"clave": "c", "texto": "En la unidad fiscal especializada de acceso a la justicia."}]$q$::jsonb, $q$a$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3004, $q$Búsqueda web: Fallo Bahamondez, Marcelo s/ medida cautelar, la CSJN$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "hizo lugar al pronunciamiento apelado, en cuanto la libertad de una persona adulta de tomar decisiones se encuentra limitada por el interés público."}, {"clave": "b", "texto": "se declaró incompetente por considerar que la decisión sobre el propio cuerpo no es materia justiciable."}, {"clave": "c", "texto": "Consideró que no existió en el caso ningún interés público relevante que justificara la restricción en la libertad personal del nombrado"}]$q$::jsonb, $q$c$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3005, $q$Realice una búsqueda web a través de la página del MPF u otros sitios que considere pertinentes y encuentre la Resolución PGN 914/12 que crea a la Procuraduría de Criminalidad Económica y Lavado de Activos (PROCELAC). Luego responda: Según la Resolución mencionada, ¿cuál de las siguientes oficinas pertenece al área operativa de PROCELAC?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Mercado de Capitales."}, {"clave": "b", "texto": "Análisis Criminal."}, {"clave": "c", "texto": "Trata de Personas."}]$q$::jsonb, $q$a$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3006, $q$Realice una búsqueda web y marque la opción correcta en el siguiente ejercicio de opción múltiple: En el fallo Kot, Samuel S.R.L., s/recurso de hábeas corpus la Corte Suprema de Justicia de la Nación:$q$, 'multiple_choice', $q$[{"clave": "i", "texto": "Circunscribió la protección de los derechos humanos a los ataques que provienen de la autoridad y sostuvo que en ningún caso procede cuando la restricción ilegítima es causada por actos de particulares."}, {"clave": "ii", "texto": "Amplió la esfera de acción del recurso de amparo al establecerse que también es viable deducirlo cuando la violación de un derecho provenga de un particular."}, {"clave": "iii", "texto": "Consideró legítima la restricción por parte de los obreros, ya que la ley les otorga la facultad de recurrir por sí mismos a actos para defender lo que estimen su derecho."}]$q$::jsonb, $q$ii$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3007, $q$Realice una búsqueda web y marque la opción correcta en el siguiente ejercicio de opción múltiple: En el fallo Siri, Ángel, s/interpone recurso de hábeas corpus la Corte Suprema de Justicia de la Nación:$q$, 'multiple_choice', $q$[{"clave": "i", "texto": "Confirmó la sentencia de la Cámara de Apelaciones argumentado que la no existencia de una base normativa para la actuación jurisdiccional solo es admisible en condiciones vitalmente extremas."}, {"clave": "ii", "texto": "Revocó la sentencia de la Cámara de Apelaciones ordenándole a la autoridad policial el cese de la restricción impuesta en tanto las garantías individuales existen y protegen a los individuos por el sólo hecho de estar consagradas en la Constitución Nacional."}, {"clave": "iii", "texto": "Consideró que la solicitud efectuada era improcedente porque no se había violado la libertad física de ninguna persona y que, en consecuencia, la medida no resultaba contraria a los derechos y garantías constitucionales."}]$q$::jsonb, $q$ii$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3008, $q$En el fallo Indalia PONZETTI DE BALBIN c/ Editorial Atlántida S.A. s/ daños y perjuicios la CSJN:$q$, 'multiple_choice', $q$[{"clave": "i", "texto": "Admitió el recurso y confirmó la sentencia, ya que en el caso se trata de establecer los límites jurídicos del derecho de información en relación directa con el derecho de la privacidad o intimidad (art 19 CN)."}, {"clave": "ii", "texto": "Rechazó el recurso extraordinario, porque consideró que en el caso se encuentra en juego el derecho constitucional de publicar las ideas por la prensa sin censura previa (art 14CN)."}, {"clave": "iii", "texto": "Admitió el recurso y confirmo la sentencia, porque en caso se debe privilegiar el derecho a la privacidad o intimidad de una persona pública como el ex presidente de la nación."}]$q$::jsonb, $q$i$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3009, $q$Realice una búsqueda web a través de la página del MPF u otros sitios que considere pertinentes y encuentre la Resolución PGN 208/13 que crea a la Procuraduría de Narcocriminalidad (PROCUNAR). Luego responda: según la Resolución mencionada, ¿cuál de las siguientes oficinas pertenece al área operativa de PROCUNAR?$q$, 'multiple_choice', $q$[{"clave": "i", "texto": "Información e investigaciones."}, {"clave": "ii", "texto": "Mercado de capitales."}, {"clave": "iii", "texto": "Lavado de activos."}]$q$::jsonb, $q$i$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3010, $q$En el fallo - Transexual c/ Inspección General de Justicia s/recurso de hecho la Corte Suprema de Justicia de la Nación:$q$, 'multiple_choice', $q$[{"clave": "i", "texto": "Desestimó el recurso por no considerarlo una cuestión federal, ya que se trata de la interpretación inconstitucional de normas no federales."}, {"clave": "ii", "texto": "Resolvió de conformidad con el art. 33, segunda parte, ap. 1°, del Código Civil y sostuvo que el fin útil que debe perseguir una asociación civil debe serlo no sólo para sus integrantes, sino para la comunidad en la cual se refleja el actuar de sus entidades."}, {"clave": "iii", "texto": "Declaró procedente el recurso, consagrando el derecho a la igualdad y de asociarse pacíficamente, en atención a las obligaciones que tiene el Estado conforme al art. 75 inc. 22 de la Constitución Nacional."}]$q$::jsonb, $q$ii$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 3011, $q$En el fallo Asociación Lucha por la Identidad Travesti-Transexual c/ Inspección General de Justicia s/ recurso de hecho la Corte Suprema de Justicia de la Nación:$q$, 'multiple_choice', $q$[{"clave": "i", "texto": "Resolvió de conformidad con el art 33, segunda parte, ap. 1°, del Código Civil y sostuvo que el fin útil que debe perseguir una asociación civil debe serlo no solo para sus integrantes, sino para comunidad en la cual se refleja el actuar de sus entidades."}, {"clave": "ii", "texto": "Desestimó el recurso por no considerarlo una cuestión federal, ya que se trata de la interpretación inconstitucional de normas no federales."}, {"clave": "iii", "texto": "Declaró precedente el recurso, consagrando el derecho a la igualdad y de asociarse pacíficamente, en atención a las obligaciones que tiene el Estado conforme al art. 75 inc 22 de la CN."}]$q$::jsonb, $q$iii$q$, $q$mpf-modelos-manual$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 4021, $q$Realice una búsqueda web a través de la página del Ministerio Público Fiscal u otros sitios que considere convenientes y ubique dónde se encuentra la Sede Fiscal Descentralizada de Caleta Olivia. Luego responda la siguiente consigna: ¿A qué jurisdicción del MPF pertenece?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Córdoba."}, {"clave": "b", "texto": "Tierra del Fuego."}, {"clave": "c", "texto": "Comodoro Rivadavia."}]$q$::jsonb, $q$c$q$, $q$mpf-preguntero-nexo$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 4022, $q$Realice una búsqueda web a través de la página del Ministerio Público Fiscal u otros sitios que considere convenientes y ubique dónde se encuentra la Fiscalía Federal de Junín. Luego responda la siguiente consigna: ¿A qué jurisdicción del MPF pertenece?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "La Pampa."}, {"clave": "b", "texto": "La Plata."}, {"clave": "c", "texto": "Mar del Plata."}]$q$::jsonb, $q$b$q$, $q$mpf-preguntero-nexo$q$, $q$Búsqueda e investigación$q$, 'media', false),
  ((select id from examen), 4023, $q$Dentro del fallo de la Corte Suprema de Justicia de la Nación “Albarracín Nieves, Jorge Washington s/ medidas precautorias”, en su considerando 19° la Corte afirma que:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "El consentimiento informado puede ser omitido por los profesionales de la salud si el tratamiento resulta beneficioso para el paciente."}, {"clave": "b", "texto": "No resultaría constitucionalmente justificada una resolución judicial que autorizara a someter a una persona adulta a un tratamiento en contra de su voluntad."}, {"clave": "c", "texto": "Como el paciente no se encontraba en condiciones de expresarse por sí misma, su cónyuge es quien tiene la potestad de expresar su consentimiento."}]$q$::jsonb, $q$b$q$, $q$mpf-preguntero-nexo$q$, $q$Búsqueda e investigación$q$, 'media', false)
on conflict (exam_id, orden) do update set
  enunciado        = excluded.enunciado,
  tipo             = excluded.tipo,
  opciones         = excluded.opciones,
  respuesta_correcta = excluded.respuesta_correcta,
  fuente_normativa = excluded.fuente_normativa,
  -- El tema tampoco se pisa: si alguien lo corrigió a mano al revisar, la
  -- propuesta de la regla no tiene por qué ganarle.
  tema             = coalesce(questions.tema, excluded.tema),
  confianza        = excluded.confianza,
  -- revisada NO se pisa: si alguien ya revisó una pregunta a mano, volver a
  -- correr esto no le saca el tilde.
  revisada         = questions.revisada;

-- MPF · teorico · multiple_choice
-- fuentes: mpf-modelos-manual, mpf-preguntero-nexo
with examen as (
  select e.id from exams e
    join concursos c on c.id = e.concurso_id
   where c.organismo = 'mpf' and c.cargo = 'Técnico administrativo' and c.anio = 2026
     and e.instancia = 'teorico' and e.modalidad = 'multiple_choice'
)
insert into questions (
  exam_id, orden, enunciado, tipo, opciones, respuesta_correcta,
  fuente_normativa, tema, confianza, revisada
) values
