  ((select id from examen), 3164, $q$El nuevo Código Procesal Penal Federal permite:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Ordenar de manera más precisa los expedientes escritos para llevar un registro más exhaustivo de los casos."}, {"clave": "b", "texto": "Concentrar los esfuerzos y estrategias de fiscales en delitos de impacto social y de interés público."}, {"clave": "c", "texto": "Diversificar los esfuerzos y estrategias de fiscales en múltiples delitos de bajo impacto social."}]$q$::jsonb, $q$b$q$, $q$mpf-modelos-manual$q$, $q$Código Procesal Penal Federal$q$, 'media', false),
