  ((select id from examen), 3166, $q$El nuevo Código Procesal Penal Federal permite:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Ordenar de manera más precisa los expedientes escritos para llevar un registro más exhaustivo de los casos."}, {"clave": "b", "texto": "Concentrar los esfuerzos y estrategias de fiscales en delitos de impacto social y de interés público."}, {"clave": "c", "texto": "Diversificar los esfuerzos y estrategias de fiscales en múltiples delitos de bajo impacto social."}]$q$::jsonb, $q$b$q$, $q$mpf-modelos-manual$q$, $q$Código Procesal Penal Federal$q$, 'media', false),
  ((select id from examen), 3167, $q$¿Qué nuevo actor emergió en el espacio político en el marco de la transición a la democracia?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Los organismos de Derechos Humanos."}, {"clave": "b", "texto": "Los partidos políticos."}, {"clave": "c", "texto": "Los sindicatos."}]$q$::jsonb, $q$a$q$, $q$mpf-modelos-manual$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4001, $q$La competencia federal:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Alcanza todas las causas salvo que las provincias definan lo contrario."}, {"clave": "b", "texto": "Se encuentra expresamente asignada por normas de la Constitución Nacional y leyes dictadas por el Congreso de la Nación."}, {"clave": "c", "texto": "Se encuentra definida por el Ministerio de Justicia, de acuerdo a los criterios determinados por el Poder Ejecutivo Nacional."}]$q$::jsonb, $q$b$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'alta', false),
  ((select id from examen), 4002, $q$¿Qué diferencia existe respecto de los alcances territoriales que tienen los distintos códigos de procedimiento que rigen en el país?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Los códigos de procedimiento nacionales rigen exclusivamente en el territorio de la Ciudad Autónoma de Buenos Aires y los provinciales en el territorio de cada provincia."}, {"clave": "b", "texto": "No existe tal diferencia, ya que los códigos de procedimiento rigen del mismo modo en todo el territorio nacional."}, {"clave": "c", "texto": "Los códigos de procedimiento nacionales rigen en todo el territorio para causas federales y, en la Ciudad Autónoma de Buenos Aires para la justicia nacional, los provinciales son de aplicación en el territorio de cada provincia."}]$q$::jsonb, $q$c$q$, $q$mpf-preguntero-nexo$q$, $q$Historia argentina y latinoamericana$q$, 'alta', false),
  ((select id from examen), 4003, $q$Para fomentar la inmigración europea, durante los últimos años del siglo XIX se dictaron las leyes de:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Vivienda, Promoción de la navegación y Aduanas."}, {"clave": "b", "texto": "Vivienda, Sufragio secreto y obligatorio y Libertad de asociación sindical."}, {"clave": "c", "texto": "Educación laica, gratuita y obligatoria, Matrimonio Civil y Registro Civil."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Historia argentina y latinoamericana$q$, 'media', false),
  ((select id from examen), 4004, $q$¿Qué nuevo actor emergió en el espacio político en el marco de la transición a la democracia durante la década de 1980?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Los organismos de Derechos Humanos."}, {"clave": "b", "texto": "Los partidos políticos."}, {"clave": "c", "texto": "Los sindicatos."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Historia argentina y latinoamericana$q$, 'media', false),
  ((select id from examen), 4005, $q$El asesinato de José Ignacio Rucci en 1973 significó:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "El cierre del ciclo de violencia política iniciado en 1970 con el asesinato de Pedro Eugenio Aramburu."}, {"clave": "b", "texto": "La ruptura definitiva entre los sectores de la derecha y la izquierda peronistas."}, {"clave": "c", "texto": "La fractura de la Unión Obrera Metalúrgica."}]$q$::jsonb, $q$b$q$, $q$mpf-preguntero-nexo$q$, $q$Historia argentina y latinoamericana$q$, 'media', false),
  ((select id from examen), 4006, $q$Es posible sustituir a un miembro del Ministerio Público Fiscal de la Nación:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "en caso de recusación y excusación."}, {"clave": "b", "texto": "nunca es posible la sustitución de sus integrantes."}, {"clave": "c", "texto": "ninguna de las opciones anteriores es correcta."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Ordenamiento del MPF$q$, 'media', false),
  ((select id from examen), 4007, $q$¿Qué propone la nueva estructura del Ministerio Publico Fiscal en el marco de la implementación del sistema acusatorio?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "La organización de las fiscalías a partir de un diseño en reflejo al del Poder Judicial."}, {"clave": "b", "texto": "Un modelo de organización dinámico en función de las necesidades de cada jurisdicción."}, {"clave": "c", "texto": "La creación de una única Unidad Fiscal Centralizada que actúa frente a todos los órganos jurisdiccionales."}]$q$::jsonb, $q$b$q$, $q$mpf-preguntero-nexo$q$, $q$Código Procesal Penal Federal$q$, 'media', false),
  ((select id from examen), 4008, $q$La Convención Americana sobre Derechos Humanos entiende a la persona como:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Todo ser humano."}, {"clave": "b", "texto": "Mayor de 18 años."}, {"clave": "c", "texto": "Ciudadano de un Estado."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'alta', false),
  ((select id from examen), 4009, $q$Según la Constitución Nacional:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "los derechos y garantías sancionados son absolutos y no admiten ningún tipo de restricción."}, {"clave": "b", "texto": "los derechos y garantías reconocidos en el cuerpo constitucional ceden inevitablemente ante las necesidades del Estado."}, {"clave": "c", "texto": "los derechos y garantías sancionados no pueden ser alterados por las leyes que los reglamentan."}]$q$::jsonb, $q$c$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4010, $q$Los auxiliares fiscales:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Asisten a todas las audiencias y litigan en todas las causas a cargo del fiscal."}, {"clave": "b", "texto": "Realizan sus actividades sin las instrucciones y por fuera de la supervisión de los fiscales."}, {"clave": "c", "texto": "Actúan bajo las instrucciones, supervisión y responsabilidad de los magistrados del Ministerio Público Fiscal."}]$q$::jsonb, $q$c$q$, $q$mpf-preguntero-nexo$q$, $q$Ordenamiento del MPF$q$, 'alta', false),
  ((select id from examen), 4011, $q$Según la Convención Americana de Derechos Humanos, durante el proceso de investigación de un delito, toda persona imputada tiene derecho a:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "la comunicación previa y detallada de la acusación formulada."}, {"clave": "b", "texto": "impulsar la investigación para dinamizar los tiempos procesales."}, {"clave": "c", "texto": "obtener su absolución cuando el proceso judicial exceda los cuatro años de duración."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Código Procesal Penal Federal$q$, 'media', false),
  ((select id from examen), 4012, $q$Las jurisdicciones en que se divide la estructura interna del Ministerio Público Fiscal de la Nación:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Se ajustan a criterios de conveniencia como la densidad poblacional, la comunicación o cercanía interprovincial y la cantidad de causas tramitadas."}, {"clave": "b", "texto": "Coinciden en todos los casos con los límites provinciales."}, {"clave": "c", "texto": "No reflejan de ningún modo la distribución territorial del Poder Judicial de la Nación."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Ordenamiento del MPF$q$, 'media', false),
  ((select id from examen), 4013, $q$Con la presentación de la demanda:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Se inicia un proceso judicial."}, {"clave": "b", "texto": "Comienza la etapa de alegatos."}, {"clave": "c", "texto": "Culmina la etapa probatoria."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'alta', false),
  ((select id from examen), 4014, $q$El derecho de peticionar a las autoridades:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "No se encuentra estipulado en nuestra carta magna."}, {"clave": "b", "texto": "Está garantizado por la Constitución Nacional."}, {"clave": "c", "texto": "Fue implementado por una resolución del Ministerio del Interior."}]$q$::jsonb, $q$b$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4015, $q$¿Según qué teoría del Estado es posible a través de la intervención combinar el crecimiento económico con un reparto equitativo de los resultados de ese crecimiento?$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Estado Federal."}, {"clave": "b", "texto": "Estado Liberal."}, {"clave": "c", "texto": "Estado de Bienestar."}]$q$::jsonb, $q$c$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4016, $q$Los tratados internacionales sobre Derechos Humanos incorporados en el art. 75 inc. 22 a la Constitución Nacional:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "tienen jerarquía constitucional, superior a las leyes, y deben interpretarse de manera complementaria de los derechos y garantías por ella reconocidos."}, {"clave": "b", "texto": "tienen jerarquía inferior a las leyes pero señalan orientaciones deseables para la Constitución."}, {"clave": "c", "texto": "tienen jerarquía superior a las leyes y a la Constitución Nacional por tratarse de normas de aplicación internacional."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4017, $q$El artículo 14 de la Constitución Nacional protege:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Los derechos judiciales."}, {"clave": "b", "texto": "Los derechos económicos."}, {"clave": "c", "texto": "Los derechos civiles."}]$q$::jsonb, $q$c$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4018, $q$Según la Constitución Nacional, corresponde al jefe de gabinete:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "enviar al Congreso los proyectos de ley de ministerios y de presupuesto nacional."}, {"clave": "b", "texto": "disponer la intervención federal a una provincia o a la ciudad de Buenos Aires."}, {"clave": "c", "texto": "presidir la cámara de senadores, aunque no tiene voto sino en el caso que haya empate en la votación."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Sistema constitucional$q$, 'media', false),
  ((select id from examen), 4019, $q$Si el delito es de acción pública, acción penal es iniciada de oficio por:$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "El Ministerio Público Fiscal."}, {"clave": "b", "texto": "La querella."}, {"clave": "c", "texto": "El juez."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Ordenamiento del MPF$q$, 'media', false),
  ((select id from examen), 4020, $q$Aunque las diferentes formas de violencia contra la mujer generalmente aparecen de manera concomitante, entre estos ¿de qué modo específico se ejerce violencia$q$, 'multiple_choice', $q$[{"clave": "a", "texto": "Humillando o atentando públicamente contra la dignidad de aquellas."}, {"clave": "b", "texto": "Sustrayéndoles indebidamente sus instrumentos de trabajo."}, {"clave": "c", "texto": "Exigiendoles obediencia y sumisión."}]$q$::jsonb, $q$a$q$, $q$mpf-preguntero-nexo$q$, $q$Problemática de género$q$, 'media', false)
on conflict (exam_id, orden) do update set
  enunciado        = excluded.enunciado,
  tipo             = excluded.tipo,
  opciones         = excluded.opciones,
  respuesta_correcta = excluded.respuesta_correcta,
  fuente_normativa = excluded.fuente_normativa,
  -- El tema tampoco se pisa: si alguien lo corrigió a mano al revisar, la
  -- propuesta de la regla no tiene por qué ganarle.
  tema             = coalesce(questions.tema, excluded.tema),
  confianza        = excluded.confianza,
  -- revisada NO se pisa: si alguien ya revisó una pregunta a mano, volver a
  -- correr esto no le saca el tilde.
  revisada         = questions.revisada;

-- MPD · practico · tipeo
-- 3 textos de práctica, no oficiales. Ver PLAN-SIMULADOR.md §6.
with examen as (
  select e.id from exams e
    join concursos c on c.id = e.concurso_id
   where c.organismo = 'mpd' and c.cargo = 'Técnico administrativo' and c.anio = 2026
     and e.instancia = 'practico' and e.modalidad = 'tipeo'
)
insert into questions (
  exam_id, orden, enunciado, tipo, opciones, respuesta_correcta,
  fuente_normativa, tema, confianza, revisada
)
select (select id from examen), t.orden, t.texto, 'tipeo', '[]'::jsonb, t.texto,
       t.fuente, 'Tipeo', 'media', true
from (values
  (1, $q$El Ministerio Público de la Defensa es una institución de defensa y protección de derechos humanos que garantiza el acceso a la justicia y la asistencia jurídica integral, en casos individuales y colectivos, según los principios establecidos en su ley orgánica. Promueve toda medida tendiente a la protección de los derechos fundamentales de las personas, en especial de quienes se encuentren en situación de vulnerabilidad.

En el ejercicio de sus funciones, los magistrados, funcionarios y empleados observan los principios de unidad de actuación, independencia, autonomía funcional y autarquía financiera. Ningún integrante puede recibir instrucciones de autoridades ajenas a la institución, ni desempeñar tareas incompatibles con su cargo.

La actuación se rige por criterios de celeridad, sencillez y economía procesal, procurando que cada trámite se resuelva en el menor plazo posible.$q$, $q$texto de práctica: Ley Orgánica del Ministerio Público de la Defensa$q$),
  (2, $q$Buenos Aires, marzo de 2026.

VISTO: el expediente N° 3.472/2026, caratulado «Solicitud de asistencia jurídica — Dirección General de Acceso a la Justicia», y

CONSIDERANDO: Que se solicita la designación de un profesional que asuma la representación de la persona requirente ante el Juzgado Federal N° 2.

Que el artículo 42 de la Ley N° 27.149 establece que corresponde a la Defensoría General de la Nación proveer lo necesario para garantizar el efectivo acceso a la justicia, y que la solicitud reúne los requisitos exigidos por la reglamentación vigente.

Que se ha verificado que la persona no cuenta con recursos suficientes para afrontar el proceso, según surge de la declaración jurada obrante a fojas 7/9.

Por ello, SE RESUELVE: 1°) Hacer lugar a lo solicitado. 2°) Registrar, notificar y archivar.$q$, $q$texto de práctica: Resolución de trámite$q$),
  (3, $q$Toda presentación que ingrese por Mesa de Entradas debe recibir cargo con fecha y hora, sin excepción. El agente que la reciba verificará que esté firmada, que indique el número de expediente al que corresponde y que acompañe la documentación mencionada; si faltara alguno de esos elementos, dejará constancia en el cargo y avisará a la Secretaría.

Las presentaciones urgentes —medidas cautelares, habeas corpus, plazos que vencen el mismo día— se identifican con una carátula que dice «URGENTE» y se giran en el acto, sin esperar el reparto habitual de las 13:00.

Los expedientes en préstamo se registran en el libro correspondiente con el nombre completo de quien los retira, su dependencia y la fecha comprometida para la devolución. Ningún expediente sale del edificio sin autorización escrita de la Secretaría.$q$, $q$texto de práctica: Instructivo de mesa de entradas$q$)
) as t(orden, texto, fuente)
on conflict (exam_id, orden) do update set
  enunciado        = excluded.enunciado,
  tipo             = excluded.tipo,
  opciones         = excluded.opciones,
  respuesta_correcta = excluded.respuesta_correcta,
  fuente_normativa = excluded.fuente_normativa,
  tema             = coalesce(questions.tema, excluded.tema),
  confianza        = excluded.confianza,
  revisada         = questions.revisada;
